  охотник:   { порогАтаки: +4, рабочих: 0,  доляОхраны: 0,  решимость: 0, плюс: ['прокачка', 'выжидание', 'ударныйкулак', 'ценнаядобыча', 'лечение', 'разведка', 'копить'], минус: ['налёт'] },
