    курьерСдаёт: курьерСдаёт === null ? КУРЬЕР_СДАЁТ : +курьерСдаёт,
    курьер: 0,
    тактШтаба: у.тактШтаба, тактОтрядов: у.тактОтрядов, тактБойца: у.тактБойца,
    разведчиков: у.разведчиков ?? 1, охотаРадиус: у.охотаРадиус ?? 45, бабыОхотятся: у.бабыОхотятся !== false,
    память: у.память, решимость: Math.max(1, Math.min(3, у.решимость + (х.решимость || 0))), осторожность: у.осторожность,
    порогАтаки: Math.max(2, у.порогАтаки + х.порогАтаки),
