    // давал про отряд первой миссии кампании — там ни склада, ни домов, и носить нечего. Но
    // поставлено оно было НА ВСЕХ, и в схватке это убило хозяйство: замер одиночного прогона на
    // Ashfall (tools/ai_курьер.mjs, 10 минут, соперников нет) — до правки 12 бойцов и 11850 еды
