    с.разведано = new Set(з.разведано || []);
    с.неберётся = new Set(з.неберётся || []);
    с.разведЦели = new Map((з.разведЦели || []).map(([i, x, y, срок]) => [i, { x, y, срок }]));
    с.курьеры = new Map((з.курьеры || []).map(([i, x, y, до]) => [i, { x, y, до }]));
    for (const k of Object.keys(з.отряды || {})) с.отряды[k] = (з.отряды[k] || []).slice();
